mapper.select:
/*selectMasterWmGrTrWarhsngProgressManageList*/ SELECT Y.BUYER_NAME, Y.PO_NO, Y.INV_NO, Y.STDCATLG_ID, Y.PO_CREATE_DATE, Y.WMS_GR_DATE, Y.PO_QTY, Y.AGENT_PRICE, Y.AGENT_ITEM_AMT, Y.STATUS, Y.LEGACY_PO_NO, Y.PORS_CD_DATE, Y.BUYER_ITEM_NO, Y.RD_DATE, Y.ADD_USER_ID, Y.INV_QTY, Y.UNIT_PRICE, Y.ITEM_AMT, Y.DESCRIPTION, Y.SPECIFICATION, Y.AGENT, Y.GI_GR_QTY, Y.DELY_TO_LOCATION, Y.PO_REMARK, Y.ADD_USER_NAME AS ADD_USER_NAME, Y.ADD_USER_TEL AS ADD_USER_TEL, Y.POHD_REMARK, Y.BUYER, Y.DOC_TYPE, Y.MASTER_ITEM, Y.IMG_NO, Y.BYIT_COMORG_CODE , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.AGENT_NAME||'('||Y.AGENT_TEL_NO||')' AGENT_NAME, Y.AGENT_NAME AGENT_NAME_ORG, Y.AGENT_TEL_NO AGENT_TEL_NO ,Y.WMS_GR_QTY,Y.WMS_IVK_QTY ,Y.DOC_TEXT ,(SELECT DECODE(COUNT(DISTINCT PODT1.PROCESS_TYPE),1,DECODE(MAX(DISTINCT PODT1.PROCESS_TYPE),'1','재고','2','TR','3','VMI'),'통합(일반)') FROM ICOMPODT PODT1 WHERE PODT1.LEGACY_PO_NO = Y.LEGACY_PO_NO AND PODT1.BUYER = Y.BUYER ) AS GUBUN ,(SELECT DECODE(MAX(DISTINCT PODT1.PROCESS_TYPE),'1','재고','2','TR','3','VMI') FROM ICOMPODT PODT1 WHERE PODT1.LEGACY_PO_NO = Y.LEGACY_PO_NO AND PODT1.BUYER = Y.BUYER ) AS STATUS_TEXT ,Y.BOX_QTY, Y.CAR_NO , Y.CAR_PERSON_NAME , Y.CAR_PERSON_TEL,
Y.HUB_YN, Y.DEST_WAREHOUSE FROM (
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_NAME, PODT.PO_NO, '' AS INV_NO, CQDT.STDCATLG_ID, POHD.PO_CREATE_DATE, '' AS WMS_GR_DATE, PODT.ITEM_QTY AS PO_QTY, PODT.AGENT_PRICE, PODT.AGENT_ITEM_AMT, '발주' AS STATUS, PODT.LEGACY_PO_NO, '' AS PORS_CD_DATE, PODT.BUYER_ITEM_NO, PODT.RD_DATE , PRDT.ADD_USER_ID , 0 AS INV_QTY, PODT.UNIT_PRICE, PODT.ITEM_AMT, PODT.DESCRIPTION, PODT.SPECIFICATION, POHD.AGENT, 0 AS GI_GR_QTY, POHD.DELY_TO_LOCATION, PODT.PO_REMARK, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.PO_REMARK AS POHD_REMARK, PODT.BUYER, DECODE(POHD.DOC_TYPE,'S','선입고' ,'X','Kepmro'||(SELECT DECODE(PRE_GR_FLAG, 'Y', ' 선입고', '') FROM ICOMPRHD WHERE BUYER = PRDT.BUYER AND PR_NO = PRDT.PR_NO AND STATUS <> 'D') ,'일반') AS DOC_TEXT , POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_TEL_NO ,0 AS WMS_GR_QTY , 0 AS WMS_IVK_QTY ,'' SCHEDULED_DATE, 0 BOX_QTY, '' CAR_NO , '' CAR_PERSON_NAME , '' CAR_PERSON_TEL, 'N' AS HUB_YN, '' AS DEST_WAREHOUSE FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT , ICOMCQDT CQDT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = CQDT.BUYER(+) AND PODT.CONTRACT_NO = CQDT.CONTRACT_NO(+) AND PODT.CONTRACT_SEQ = CQDT.CONTRACT_SEQ(+) AND PODT.ITEM_QTY > PODT.IV_QTY AND PODT.COMPLETE_MARK = 'N' AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND PODT.PROCESS_TYPE = '2' AND PODT.WAREHOUSE_CODE =#{st_warehouse_code} AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER IN
#{st_buyer_code}
AND POHD.AGENT = #{st_agent_code}
AND CQDT.STDCATLG_ID = #{st_stdcatlg_id}
AND PODT.BUYER_ITEM_NO LIKE #{st_buyer_item_no}||'%'
AND PODT.DESCRIPTION LIKE '%'||#{st_description}||'%'
AND PODT.PO_NO = #{st_inv_no}
UNION ALL
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PODT.BUYER) AS BUYER_NAME, PODT.PO_NO, IVDT.INV_NO AS INV_NO, CQDT.STDCATLG_ID, POHD.PO_CREATE_DATE, IVDT.WMS_GR_DATE AS WMS_GR_DATE, PODT.ITEM_QTY AS PO_QTY, PODT.AGENT_PRICE, PODT.AGENT_ITEM_AMT, DECODE(PODT.ITEM_QTY, (SELECT SUM(WMS_GR_QTY) FROM ICOMIVDT WHERE BUYER=PODT.BUYER AND PO_NO=PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D'),'입고완료',IVDT.INV_QTY,'입고예정',DECODE(IVDT.INV_QTY,IVDT.WMS_GR_QTY,'분할입고완료','분할입고예정')) AS STATUS , PODT.LEGACY_PO_NO, PODT.RD_DATE AS PORS_CD_DATE, PODT.BUYER_ITEM_NO, PODT.RD_DATE , PRDT.ADD_USER_ID , IVDT.INV_QTY AS INV_QTY, PODT.UNIT_PRICE, PODT.ITEM_AMT, PODT.DESCRIPTION, PODT.SPECIFICATION, POHD.AGENT, NVL((SELECT SUM(SUB_IV.WMS_GR_QTY) FROM ICOMPODT SUB_PO,ICOMIVDT SUB_IV WHERE SUB_PO.BUYER = SUB_IV.BUYER AND SUB_PO.PO_NO = SUB_IV.PO_NO AND SUB_PO.PO_SEQ = SUB_IV.PO_SEQ AND SUB_PO.PO_NO = PODT.PO_NO AND SUB_PO.PO_SEQ = PODT.PO_SEQ AND SUB_PO.BUYER = PODT.BUYER GROUP BY SUB_PO.BUYER, SUB_PO.PO_NO, SUB_PO.PO_SEQ ),0) AS GI_GR_QTY, POHD.DELY_TO_LOCATION, PODT.PO_REMARK, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.PO_REMARK AS POHD_REMARK, PODT.BUYER, DECODE(POHD.DOC_TYPE,'S','선입고' ,'X','Kepmro'||(SELECT DECODE(PRE_GR_FLAG, 'Y', ' 선입고', '') FROM ICOMPRHD WHERE BUYER = PRDT.BUYER AND PR_NO = PRDT.PR_NO AND STATUS <> 'D') ,'일반') AS DOC_TEXT , POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT)AS AGENT_NAME , (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_TEL_NO ,NVL(IVDT.WMS_GR_QTY,0) AS WMS_GR_QTY, NVL(IVDT.WMS_IVK_QTY,0) AS WMS_IVK_QTY ,IVDT.SCHEDULED_DATE, IVDT.BOX_QTY, IVDT.CAR_NO , IVDT.CAR_PERSON_NAME , IVDT.CAR_PERSON_TEL, 'N' AS HUB_YN, '' AS DEST_WAREHOUSE FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT, ICOMIVDT IVDT, ICOMCQDT CQDT WHERE PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.BUYER = CQDT.BUYER(+) AND PODT.CONTRACT_NO = CQDT.CONTRACT_NO(+) AND PODT.CONTRACT_SEQ = CQDT.CONTRACT_SEQ(+) AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND PRDT.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND PODT.PROCESS_TYPE = '2' AND PODT.WAREHOUSE_CODE = #{st_warehouse_code}
AND IVDT.INV_QTY > 0 AND PODT.ITEM_QTY <> (SELECT SUM(WMS_GR_QTY)FROM ICOMIVDT WHERE BUYER=PODT.BUYER AND PO_NO=PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D')
AND (PODT.ITEM_QTY <> IVDT.INV_QTY AND PODT.ITEM_QTY <> (SELECT SUM(WMS_GR_QTY)FROM ICOMIVDT WHERE BUYER=PODT.BUYER AND PO_NO=PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D'))
AND PODT.ITEM_QTY = (SELECT SUM(WMS_GR_QTY)FROM ICOMIVDT WHERE BUYER=PODT.BUYER AND PO_NO=PODT.PO_NO AND PO_SEQ = PODT.PO_SEQ AND STATUS <> 'D')
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND IVDT.WMS_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER in
#{st_buyer_code}
AND POHD.AGENT = #{st_agent_code}
AND CQDT.STDCATLG_ID = #{st_stdcatlg_id}
AND PODT.BUYER_ITEM_NO LIKE #{st_buyer_item_no}||'%'
AND PODT.DESCRIPTION LIKE #{st_description}||'%'
AND IVDT.INV_NO = #{st_inv_no}
UNION ALL
SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = HUB.BUYER) AS BUYER_NAME, PODT.PO_NO AS PO_NO, HUB.S_INV_NO AS INV_NO, '' AS STDCATLG_ID, POHD.PO_CREATE_DATE AS PO_CREATE_DATE, TO_CHAR(HUB.HUB_GR_CREATE_DATE, 'YYYYMMDD') AS WMS_GR_DATE, PODT.ITEM_QTY AS PO_QTY, PODT.AGENT_PRICE AS AGENT_PRICE, PODT.AGENT_ITEM_AMT AS AGENT_ITEM_AMT, '간선입고완료' AS STATUS, PODT.LEGACY_PO_NO AS LEGACY_PO_NO, PODT.RD_DATE AS PORS_CD_DATE, PODT.BUYER_ITEM_NO AS BUYER_ITEM_NO, PODT.RD_DATE AS RD_DATE, PRDT.ADD_USER_ID AS ADD_USER_ID, IVDT.INV_QTY AS INV_QTY, PODT.UNIT_PRICE AS UNIT_PRICE, PODT.ITEM_AMT AS ITEM_AMT, PODT.DESCRIPTION AS DESCRIPTION, PODT.SPECIFICATION AS SPECIFICATION, POHD.AGENT, NVL(HUB.HUB_GR_QTY,0) AS GI_GR_QTY, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION, PODT.PO_REMARK AS PO_REMARK, PRDT.ADD_USER_NAME AS ADD_USER_NAME, PRDT.ADD_USER_TEL AS ADD_USER_TEL, POHD.PO_REMARK AS POHD_REMARK, PODT.BUYER, DECODE(POHD.DOC_TYPE,'S','선입고','X','Kepmro'||(SELECT DECODE(PRE_GR_FLAG,'Y',' 선입고','') FROM ICOMPRHD WHERE BUYER = PRDT.BUYER AND PR_NO = PRDT.PR_NO AND STATUS <> 'D'),'일반') AS DOC_TEXT, POHD.DOC_TYPE AS DOC_TYPE, SUBSTR(PODT.BUYER_ITEM_NO,1,7) AS MASTER_ITEM, DECODE(POHD.DOC_TYPE,'X',(SELECT NVL(TRIM(IMG_NO),'0') FROM ITEMMAST WHERE STDCATLG_ID = SUBSTR(PODT.BUYER_ITEM_NO,1,7)),'') AS IMG_NO, PODT.BYIT_COMORG_CODE AS BYIT_COMORG_CODE, PODT.CONTRACT_NO AS CONTRACT_NO, PODT.CONTRACT_SEQ AS CONTRACT_SEQ, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_NAME, (SELECT TEL_NO FROM ICOMCMPY WHERE COM_CODE = POHD.AGENT) AS AGENT_TEL_NO, NVL(IVDT.WMS_GR_QTY,0) AS WMS_GR_QTY, NVL(HUB.HUB_IV_QTY,0) AS WMS_IVK_QTY, HUB.SCHEDULED_DATE AS SCHEDULED_DATE, HUB.TOT_BOX_QTY AS BOX_QTY, '' AS CAR_NO, '' AS CAR_PERSON_NAME, '' AS CAR_PERSON_TEL, 'Y' AS HUB_YN, (SELECT TEXT7 FROM ICOMCOD1 WHERE TYPE='W001' AND FLAG='Y' AND TEXT4='B' AND TEXT1=HUB.ARRV_CENTER) AS DEST_WAREHOUSE FROM HUBIVDT HUB, ICOMIVDT IVDT, ICOMPODT PODT, ICOMPOHD POHD, ICOMPRDT PRDT WHERE 1=1 AND HUB.BUYER = IVDT.BUYER AND HUB.S_INV_NO = IVDT.INV_NO AND HUB.S_INV_SEQ = IVDT.INV_SEQ AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ = PODT.PO_SEQ AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ = PRDT.PR_SEQ AND HUB.STATUS != 'D' AND IVDT.STATUS != 'D' AND PODT.STATUS != 'D' AND POHD.STATUS != 'D' AND PRDT.STATUS != 'D' AND PODT.PROCESS_TYPE = '2' AND HUB.DEPT_CENTER = #{st_warehouse_code}
AND PODT.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND TO_CHAR(HUB.HUB_GR_CREATE_DATE, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND (PODT.PO_NO LIKE #{st_po_no}||'%' OR PODT.LEGACY_PO_NO LIKE #{st_po_no}||'%')
AND (PODT.BUYER LIKE 'KRXPR0%' OR PODT.BUYER = 'KRXPV00001')
AND PODT.BUYER IN
#{st_buyer_code}
AND POHD.AGENT = #{st_agent_code}
AND PODT.CMS_CATLG_ID = #{st_stdcatlg_id}
AND PODT.BUYER_ITEM_NO LIKE #{st_buyer_item_no}||'%'
AND PODT.DESCRIPTION LIKE #{st_description}||'%'
AND IVDT.INV_NO = #{st_inv_no}
ORDER BY RD_DATE DESC ,LEGACY_PO_NO DESC , PO_NO DESC , INV_NO, STDCATLG_ID
ORDER BY BUYER_NAME,LEGACY_PO_NO DESC , PO_NO DESC , INV_NO, STDCATLG_ID
ORDER BY AGENT_NAME,LEGACY_PO_NO, PO_NO, INV_NO, STDCATLG_ID
ORDER BY PO_NO,LEGACY_PO_NO DESC , INV_NO, STDCATLG_ID
ORDER BY INV_NO,LEGACY_PO_NO DESC , PO_NO DESC , BUYER_ITEM_NO
ORDER BY STDCATLG_ID,LEGACY_PO_NO DESC , PO_NO DESC , INV_NO
ORDER BY BUYER_ITEM_NO,LEGACY_PO_NO DESC , PO_NO DESC , INV_NO
ORDER BY DESCRIPTION,LEGACY_PO_NO DESC , PO_NO DESC , INV_NO, STDCATLG_ID
) Y
